% SPDX-License-Identifier: EUPL-1.2
:- module(m__eu_data_protection_gdpr_codes_and_certification_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2016_679_art_40_2, [label - 'Regulation (EU) 2016/679 Art 40(2) (who may prepare, amend or extend a code of conduct)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_040.002)', verbatim - 'Associations and other bodies representing categories of controllers or processors may prepare codes of conduct, or amend or extend such codes, for the purpose of specifying the application of this Regulation']).
citation(eu_reg_2016_679_art_40_3, [label - 'Regulation (EU) 2016/679 Art 40(3) (adherence to an approved code of general validity by controllers or processors not subject to the Regulation, for transfers)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_040.003)', verbatim - 'codes of conduct approved pursuant to paragraph 5 of this Article and having general validity pursuant to paragraph 9 of this Article may also be adhered to by controllers or processors that are not subject to this Regulation pursuant to Article 3']).
citation(eu_reg_2016_679_art_40_4, [label - 'Regulation (EU) 2016/679 Art 40(4) (a code shall contain monitoring mechanisms)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_040.004)', verbatim - 'A code of conduct referred to in paragraph 2 of this Article shall contain mechanisms which enable the body referred to in Article 41(1) to carry out the mandatory monitoring of compliance with its provisions']).
citation(eu_reg_2016_679_art_40_5, [label - 'Regulation (EU) 2016/679 Art 40(5) (approval of a draft code, amendment or extension by the competent supervisory authority)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_040.005)', verbatim - 'shall approve that draft code, amendment or extension if it finds that it provides sufficient appropriate safeguards']).
citation(eu_reg_2016_679_art_40_9, [label - 'Regulation (EU) 2016/679 Art 40(9) (general validity within the Union by implementing act)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_040.009)', verbatim - 'The Commission may, by way of implementing acts, decide that the approved code of conduct, amendment or extension submitted to it pursuant to paragraph 8 of this Article have general validity within the Union.']).
citation(eu_reg_2016_679_art_41_1, [label - 'Regulation (EU) 2016/679 Art 41(1) (monitoring by an accredited body with appropriate expertise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_041.001)', verbatim - 'the monitoring of compliance with a code of conduct pursuant to Article 40 may be carried out by a body which has an appropriate level of expertise in relation to the subject-matter of the code and is accredited for that purpose by the competent supervisory authority']).
citation(eu_reg_2016_679_art_41_2, [label - 'Regulation (EU) 2016/679 Art 41(2) (conditions on which a monitoring body may be accredited)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_041.002)', verbatim - 'A body as referred to in paragraph 1 may be accredited to monitor compliance with a code of conduct where that body has:']).
citation(eu_reg_2016_679_art_41_2_a, [label - 'Regulation (EU) 2016/679 Art 41(2)(a) (monitoring body: independence and expertise demonstrated)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_041.002_a)', verbatim - 'demonstrated its independence and expertise in relation to the subject-matter of the code to the satisfaction of the competent supervisory authority']).
citation(eu_reg_2016_679_art_41_2_b, [label - 'Regulation (EU) 2016/679 Art 41(2)(b) (monitoring body: eligibility, monitoring and review procedures)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_041.002_b)', verbatim - 'established procedures which allow it to assess the eligibility of controllers and processors concerned to apply the code, to monitor their compliance with its provisions and to periodically review its operation']).
citation(eu_reg_2016_679_art_41_2_c, [label - 'Regulation (EU) 2016/679 Art 41(2)(c) (monitoring body: complaint procedures and structures)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_041.002_c)', verbatim - 'established procedures and structures to handle complaints about infringements of the code or the manner in which the code has been, or is being, implemented by a controller or processor, and to make those procedures and structures transparent to data subjects and the public']).
citation(eu_reg_2016_679_art_41_2_d, [label - 'Regulation (EU) 2016/679 Art 41(2)(d) (monitoring body: no conflict of interests demonstrated)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_041.002_d)', verbatim - 'demonstrated to the satisfaction of the competent supervisory authority that its tasks and duties do not result in a conflict of interests']).
citation(eu_reg_2016_679_art_41_4, [label - 'Regulation (EU) 2016/679 Art 41(4) (duties of the monitoring body: action on infringement and informing the authority)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_041.004)', verbatim - 'take appropriate action in cases of infringement of the code by a controller or processor, including suspension or exclusion of the controller or processor concerned from the code. It shall inform the competent supervisory authority of such actions and the reasons for taking them.']).
citation(eu_reg_2016_679_art_41_5, [label - 'Regulation (EU) 2016/679 Art 41(5) (revocation of the accreditation of a monitoring body)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_041.005)', verbatim - 'The competent supervisory authority shall revoke the accreditation of a body as referred to in paragraph 1 if the requirements for accreditation are not, or are no longer, met or where actions taken by the body infringe this Regulation.']).
citation(eu_reg_2016_679_art_41_6, [label - 'Regulation (EU) 2016/679 Art 41(6) (Article 41 does not apply to processing by public authorities and bodies)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_041.006)', verbatim - 'This Article shall not apply to processing carried out by public authorities and bodies.']).
citation(eu_reg_2016_679_art_42_2, [label - 'Regulation (EU) 2016/679 Art 42(2) (certification for transfers by controllers or processors not subject to the Regulation)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_042.002)', verbatim - 'data protection certification mechanisms, seals or marks approved pursuant to paragraph 5 of this Article may be established for the purpose of demonstrating the existence of appropriate safeguards provided by controllers or processors that are not subject to this Regulation pursuant to Article 3']).
citation(eu_reg_2016_679_art_42_4, [label - 'Regulation (EU) 2016/679 Art 42(4) (certification does not reduce responsibility for compliance)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_042.004)', verbatim - 'A certification pursuant to this Article does not reduce the responsibility of the controller or the processor for compliance with this Regulation']).
citation(eu_reg_2016_679_art_42_5, [label - 'Regulation (EU) 2016/679 Art 42(5) (the issuer of a certification and its approved criteria)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_042.005)', verbatim - 'A certification pursuant to this Article shall be issued by the certification bodies referred to in Article 43 or by the competent supervisory authority, on the basis of criteria approved by that competent supervisory authority pursuant to Article 58(3) or by the Board pursuant to Article 63.']).
citation(eu_reg_2016_679_art_42_7, [label - 'Regulation (EU) 2016/679 Art 42(7) (maximum period of three years, renewal and withdrawal of a certification)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_042.007)', verbatim - 'Certification shall be issued to a controller or processor for a maximum period of three years and may be renewed, under the same conditions, provided that the relevant criteria continue to be met.']).
citation(eu_reg_2016_679_art_43_1, [label - 'Regulation (EU) 2016/679 Art 43(1) (certification bodies issue and renew certification after informing the supervisory authority; their accreditation)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_043.001)', verbatim - 'certification bodies which have an appropriate level of expertise in relation to data protection shall, after informing the supervisory authority in order to allow it to exercise its powers pursuant to point (h) of Article 58(2) where necessary, issue and renew certification.']).
citation(eu_reg_2016_679_art_43_1_a, [label - 'Regulation (EU) 2016/679 Art 43(1)(a) (accrediting entity: the competent supervisory authority)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.001_a)', verbatim - 'the supervisory authority which is competent pursuant to Article 55 or 56;']).
citation(eu_reg_2016_679_art_43_1_b, [label - 'Regulation (EU) 2016/679 Art 43(1)(b) (accrediting entity: the national accreditation body)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.001_b)', verbatim - 'the national accreditation body named in accordance with Regulation (EC) No 765/2008 of the European Parliament and of the Council in accordance with EN-ISO/IEC 17065/2012']).
citation(eu_reg_2016_679_art_43_2, [label - 'Regulation (EU) 2016/679 Art 43(2) (conditions on which a certification body is accredited)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_043.002)', verbatim - 'Certification bodies referred to in paragraph 1 shall be accredited in accordance with that paragraph only where they have:']).
citation(eu_reg_2016_679_art_43_2_a, [label - 'Regulation (EU) 2016/679 Art 43(2)(a) (certification body: independence and expertise demonstrated)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.002_a)', verbatim - 'demonstrated their independence and expertise in relation to the subject-matter of the certification to the satisfaction of the competent supervisory authority']).
citation(eu_reg_2016_679_art_43_2_b, [label - 'Regulation (EU) 2016/679 Art 43(2)(b) (certification body: undertaking to respect the approved criteria)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.002_b)', verbatim - 'undertaken to respect the criteria referred to in Article 42(5) and approved by the supervisory authority which is competent pursuant to Article 55 or 56 or by the Board pursuant to Article 63']).
citation(eu_reg_2016_679_art_43_2_c, [label - 'Regulation (EU) 2016/679 Art 43(2)(c) (certification body: issuing, periodic review and withdrawal procedures)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.002_c)', verbatim - 'established procedures for the issuing, periodic review and withdrawal of data protection certification, seals and marks']).
citation(eu_reg_2016_679_art_43_2_d, [label - 'Regulation (EU) 2016/679 Art 43(2)(d) (certification body: complaint procedures and structures)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.002_d)', verbatim - 'established procedures and structures to handle complaints about infringements of the certification or the manner in which the certification has been, or is being, implemented by the controller or processor']).
citation(eu_reg_2016_679_art_43_2_e, [label - 'Regulation (EU) 2016/679 Art 43(2)(e) (certification body: no conflict of interests demonstrated)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_043.002_e)', verbatim - 'demonstrated, to the satisfaction of the competent supervisory authority, that their tasks and duties do not result in a conflict of interests']).
citation(eu_reg_2016_679_art_43_4, [label - 'Regulation (EU) 2016/679 Art 43(4) second sentence (maximum period of five years of the accreditation of a certification body, renewal)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_043.004)', verbatim - 'The accreditation shall be issued for a maximum period of five years and may be renewed on the same conditions provided that the certification body meets the requirements set out in this Article.']).
citation(eu_reg_2016_679_art_43_7, [label - 'Regulation (EU) 2016/679 Art 43(7) (revocation of the accreditation of a certification body)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_043.007)', verbatim - 'the competent supervisory authority or the national accreditation body shall revoke an accreditation of a certification body pursuant to paragraph 1 of this Article where the conditions for the accreditation are not, or are no longer, met or where actions taken by a certification body infringe this Regulation']).

test(a_recorded_key_is_implemented) :-
    implements(eu_reg_2016_679_art_42_7).

test(an_unrecorded_key_is_not_implemented, fail) :-
    implements(eu_reg_2016_679_art_42_3).
